INSERT OR IGNORE INTO `entries` (`id`, `project_id`, `kind`, `number`, `version`, `title`, `note`, `content`, `status`, `published_at`, `notified_at`, `created`, `updated`) VALUES
('entry-sample-novel-1-1', 'sample-novel-1', 'episode', 1, '', '첫 번째 별', '예시 연재의 1화예요. 회차마다 작가의 말을 남길 수 있어요.', '[{"type":"text","text":"도서관의 마지막 불이 꺼지면 하늘에서 별이 떨어진다. 사서 윤은 그 사실을 이 도시에서 유일하게 아는 사람이었다."},{"type":"text","text":"별은 생각보다 작았다. 손바닥 위에 올려두면 체온보다 조금 따뜻했고, 귀에 가까이 대면 아주 먼 곳의 웃음소리 같은 것이 들렸다."},{"type":"text","text":"윤은 별을 주워 서고 맨 끝의 빈 책장에 꽂았다. 다음 날 아침이면 그 자리에는 한 번도 본 적 없는 제목의 책이 한 권 꽂혀 있었다."},{"type":"text","text":"오늘 떨어진 별은 유난히 파랬다. 윤이 그것을 집어 들자, 별은 작은 목소리로 말했다. \"이번엔 내 이야기를 끝까지 읽어줄 수 있어?\""},{"type":"text","text":"윤은 대답 대신 책장 앞에 의자를 끌어다 앉았다. 창밖에서 두 번째 별이 떨어지고 있었다."}]', 'published', 1792540800000, 1792540800000, 1792540800000, 1792540800000),
('entry-sample-novel-1-2', 'sample-novel-1', 'episode', 2, '', '끝까지 읽어준다는 것', '예시 연재의 2화예요. 다음 화는 준비 중이에요.', '[{"type":"text","text":"파란 별의 책은 첫 장부터 비어 있었다. 윤이 페이지를 넘길 때마다, 그녀가 읽은 만큼만 글자가 천천히 떠올랐다."},{"type":"text","text":"\"읽어주는 사람이 있어야 이야기가 생겨.\" 별이 말했다. \"지금까지 떨어진 별들은 아무도 끝까지 읽어주지 않았어.\""},{"type":"text","text":"윤은 서가를 돌아보았다. 지난 몇 년 동안 꽂아둔 책들은 모두 중간에서 멈춰 있었다. 그녀가 바빠서, 혹은 잊어서 덮어둔 책들이었다."},{"type":"text","text":"그날 밤 윤은 처음으로 한 권을 끝까지 읽었다. 마지막 장을 덮자, 책장에서 작은 빛이 새어 나와 창밖으로 날아올랐다."},{"type":"text","text":"하늘로 돌아가는 별을 보며 윤은 깨달았다. 별을 줍는 것보다 중요한 건, 끝까지 읽어주는 일이라는 것을."}]', 'published', 1792544400000, 1792544400000, 1792544400000, 1792544400000);
